import os
import re
import sys


EXTS = {'rust': 'rs', 'python': 'py', 'typescript': ('ts','tsx'), 'javascript': ('js','jsx'), 'go':'go','java':'java','c':'c'}

def run_grep(args):
    pattern=None; path='.'; max_len=80; max_count=200; context_only=False; file_type=None
    flags=[]; globs=[]; i=0; positional=[]
    while i<len(args):
        a=args[i]
        if a in ('-h','--help'):
            print('Compact grep - strips whitespace, truncates, groups by file\n\nUsage: executable grep [OPTIONS] <PATTERN> [PATH] [EXTRA_ARGS]...'); return 0
        if a in ('-l','--max-len','-m','--max','-t','--file-type') and i+1<len(args):
            val=args[i+1]; i+=2
            try:
                if a in ('-l','--max-len'): max_len=int(val)
                elif a in ('-m','--max'): max_count=int(val)
                else: file_type=val.lstrip('.')
            except ValueError: pass
            continue
        if a=='--context-only': context_only=True
        elif a in ('-n','--line-numbers'): pass
        elif a in ('-i','--ignore-case'): flags.append('i')
        elif a in ('-w','--word-regexp'): flags.append('w')
        elif a in ('-F','--fixed-strings'): flags.append('F')
        elif a in ('--glob','-g') and i+1<len(args): globs.append(args[i+1]); i+=1
        elif a.startswith('-') and len(a)>1 and a[1:].isalpha():
            flags.extend(c for c in a[1:] if c in 'iwF')
        else: positional.append(a)
        i+=1
    if positional: pattern=positional[0]
    if pattern is None:
        print('error: the following required arguments were not provided:\n  <PATTERN>',file=sys.stderr); return 2
    if len(positional)>1: path=positional[1]
    try:
        if 'F' in flags: expr=re.escape(pattern)
        else: expr=pattern
        if 'w' in flags: expr=r'(?<!\w)(?:'+expr+r')(?!\w)'
        rx=re.compile(expr,re.I if 'i' in flags else 0)
    except re.error as e:
        print(f'error: invalid regex: {e}',file=sys.stderr); return 2
    paths=[]
    def visit(p):
        if os.path.isfile(p): paths.append(p); return
        if not os.path.isdir(p): return
        for root,dirs,files in os.walk(p):
            dirs[:]=[d for d in dirs if not d.startswith('.') and d not in ('node_modules','.git','target','vendor')]
            for name in files:
                q=os.path.join(root,name)
                rel=os.path.relpath(q,path if os.path.isdir(path) else '.')
                if globs and not any(fnmatch.fnmatch(rel,g) or fnmatch.fnmatch(name,g) for g in globs): continue
                paths.append(q)
    visit(path)
    if not os.path.exists(path):
        print(f'grep: {path}: No such file or directory',file=sys.stderr); return 2
    if file_type:
        ex=EXTS.get(file_type,file_type)
        ex=(ex,) if isinstance(ex,str) else ex
        paths=[p for p in paths if os.path.splitext(p)[1].lstrip('.') in ex]
    found=[]
    for p in paths:
        try:
            with open(p,encoding='utf-8',errors='replace') as f:
                for no,line in enumerate(f,1):
                    text=line.rstrip('\r\n')
                    m=rx.search(text)
                    if not m: continue
                    text=text.lstrip()
                    if max_len>=0 and len(text)>max_len:
                        text=text[:max_len]+'...'
                    found.append((p,no,text))
        except (OSError,UnicodeError): continue
    total=len(found); files=len(set(x[0] for x in found))
    if total==0:
        print(f"0 matches for '{pattern}'"); return 1
    print(f'{total} matches in {files} files:\n')
    shown=found[:max(0,max_count)]
    for p,n,line in shown: print(f'{p}:{n}:{line}')
    if total>len(shown): print(f'[+{total-len(shown)} more]')
    return 0
